<?php require_once '../config/auth.php'; require_role('guru'); $id=(int)user_reference(); $pdo=db(); $q=$pdo->prepare("SELECT j.*,k.nama_kelas,mp.nama_mapel FROM jadwal j JOIN kelas k ON k.id_kelas=j.id_kelas JOIN mata_pelajaran mp ON mp.id_mapel=j.id_mapel WHERE j.id_guru=? AND j.hari=? ORDER BY j.jam_mulai"); $q->execute([$id,['Sunday'=>'Minggu','Monday'=>'Senin','Tuesday'=>'Selasa','Wednesday'=>'Rabu','Thursday'=>'Kamis','Friday'=>'Jumat','Saturday'=>'Sabtu'][date('l')]]); $today=$q->fetchAll(); $q=$pdo->prepare('SELECT DISTINCT k.id_kelas,k.nama_kelas FROM jadwal j JOIN kelas k ON k.id_kelas=j.id_kelas WHERE j.id_guru=? ORDER BY k.nama_kelas');$q->execute([$id]);$classes=$q->fetchAll(); $page_title='Dashboard Guru'; require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php'; ?><h2>Dashboard Guru</h2><div class="row g-4"><div class="col-lg-7"><div class="card p-3"><h5>Jadwal Hari Ini</h5><div class="table-responsive"><table class="table"><thead><tr><th>Jam</th><th>Mapel</th><th>Kelas</th><th>Ruang</th></tr></thead><tbody><?php foreach($today as $r): ?><tr><td><?= e(substr($r['jam_mulai'],0,5)) ?>–<?= e(substr($r['jam_selesai'],0,5)) ?></td><td><?= e($r['nama_mapel']) ?></td><td><?= e($r['nama_kelas']) ?></td><td><?= e($r['ruang']) ?></td></tr><?php endforeach; if(!$today): ?><tr><td colspan="4">Tidak ada jadwal hari ini.</td></tr><?php endif; ?></tbody></table></div></div></div><div class="col-lg-5"><div class="card p-3"><h5>Kelas yang Diampu</h5><?php foreach($classes as $c): ?><div class="border-bottom py-2"><?= e($c['nama_kelas']) ?></div><?php endforeach; ?><a href="nilai.php" class="btn btn-primary mt-3">Input / Edit Nilai</a></div></div></div><?php require '../includes/footer.php';
